  name        = "fw-policy"
  region      = "us-west2"
  description = "Terraform test"

  rule {
    description    = "tcp rule"
    priority       = 1000
    enable_logging = true
    action         = "allow"
    direction      = "EGRESS"

    match {
      dest_ip_ranges            = ["11.100.0.1/32"]
      dest_fqdns                = ["www.yyy.com", "www.zzz.com"]
      dest_region_codes         = ["HK", "IN"]
      dest_threat_intelligences = ["iplist-search-engines-crawlers", "iplist-tor-exit-nodes"]
      dest_address_groups       = [google_network_security_address_group.address_group_1.id]

      layer4_config {
        ip_protocol = "tcp"
        ports       = [8080, 7070]
      }
    }

    target_secure_tag {
      name = google_tags_tag_value.secure_tag_value_1.id
    }
  }

  rule {
    description    = "udp rule"
    rule_name      = "test-rule"
    priority       = 2000
    enable_logging = false
    action         = "deny"
    direction      = "INGRESS"
    disabled       = true

    match {
      src_ip_ranges            = ["0.0.0.0/0"]
      src_fqdns                = ["www.abc.com", "www.def.com"]
      src_region_codes         = ["US", "CA"]
      src_threat_intelligences = ["iplist-known-malicious-ips", "iplist-public-clouds"]
      src_address_groups       = [google_network_security_address_group.address_group_1.id]

      src_secure_tag {
        name = google_tags_tag_value.secure_tag_value_1.id
      }

      layer4_config {
        ip_protocol = "udp"
      }
    }
  }

  rule {
    description = "internal managed lb rule"
    priority    = 3000
    action      = "allow"
    direction   = "INGRESS"

    target_type = "INTERNAL_MANAGED_LB"
    target_forwarding_rules = [
      google_compute_forwarding_rule.target_forwarding_rule.self_link
    ]

    match {
      src_ip_ranges = ["10.0.0.0/8"]

      layer4_config {
        ip_protocol = "tcp"
      }
    }
  }
}

