resource "google_datastream_stream" "default" {
    depends_on = [
        google_kms_crypto_key_iam_member.key_user
    ]
    stream_id = "my-stream"
    desired_state = "NOT_STARTED"
    location = "us-central1"
    display_name = "my stream"
    labels = {
        key = "value"
    }
    source_config {
        source_connection_profile = google_datastream_connection_profile.source_connection_profile.id
        mysql_source_config {
            include_objects {
                mysql_databases {
                    database = "my-database"
                    mysql_tables {
                        table = "includedTable"
                        mysql_columns {
                            column = "includedColumn"
                            data_type = "VARCHAR"
                            collation = "utf8mb4"
                            primary_key = false
                            nullable = false
                            ordinal_position = 0
                        }
                    }
                    mysql_tables {
                        table = "includedTable_2"
                    }
                }
            }
            exclude_objects {
                mysql_databases {
                    database = "my-database"
                    mysql_tables {
                        table = "excludedTable"
                        mysql_columns {
                            column = "excludedColumn"
                            data_type = "VARCHAR"
                            collation = "utf8mb4"
                            primary_key = false
                            nullable = false
                            ordinal_position = 0
                        }
                    }
                }
            }
            max_concurrent_cdc_tasks = 5
        }
    }
    destination_config {
        destination_connection_profile = google_datastream_connection_profile.destination_connection_profile.id
        gcs_destination_config {
            path = "mydata"
            file_rotation_mb = 200
            file_rotation_interval = "60s"
            json_file_format {
                schema_file_format = "NO_SCHEMA_FILE"
                compression = "GZIP"
            }
        }
    }

    backfill_all {
        mysql_excluded_objects {
            mysql_databases {
                database = "my-database"
                mysql_tables {
                    table = "excludedTable"
                    mysql_columns {
                        column = "excludedColumn"
                        data_type = "VARCHAR"
                        collation = "utf8mb4"
                        primary_key = false
                        nullable = false
                        ordinal_position = 0
                    }
                }
            }
        }
    }

    customer_managed_encryption_key = "kms-name"
}

