resource "google_vertex_ai_pipeline_job" "pipeline_job" {
  display_name          = "example-pipeline-job"
  pipeline_job_id       = "example-pipeline-job"
  region                = "us-central1"
  preflight_validations = false
  deletion_policy       = "FORCE"

  pipeline_spec = jsonencode({
    components = {
      comp-hello-world = {
        executorLabel = "exec-hello-world"
        inputDefinitions = {
          parameters = {
            text = {
              parameterType = "STRING"
            }
          }
        }
      }
    }
    deploymentSpec = {
      executors = {
        exec-hello-world = {
          container = {
            args = [
              "--text",
              "{{$.inputs.parameters['text']}}"
            ]
            command = [
              "sh",
              "-c",
              "echo \"$0\""
            ]
            image = "python:3.11"
          }
        }
      }
    }
    pipelineInfo = {
      name = "hello-world-pipeline"
    }
    root = {
      dag = {
        tasks = {
          hello-world = {
            cachingOptions = {
              enableCache = true
            }
            componentRef = {
              name = "comp-hello-world"
            }
            inputs = {
              parameters = {
                text = {
                  componentInputParameter = "text"
                }
              }
            }
            taskInfo = {
              name = "hello-world"
            }
          }
        }
      }
      inputDefinitions = {
        parameters = {
          text = {
